//! The `languageFiles` prototype chain.
//!
//! MACHINE-DERIVED from the reference tables — do not edit by hand.
//!
//! `languageFiles` is an object *literal*, so both of the constructor's lookups
//! walk `Object.prototype`. `languageFiles['constructor']` finds `Object` and
//! is truthy, which changes the error message; `languageFiles['afinn']['toString']`
//! finds `Object.prototype.toString` and is truthy, which turns an error into a
//! successful construction with an empty vocabulary. A `HashMap` has no
//! prototype chain and would answer "not supported" to all of it.
//!
//! The tables below were produced by walking the real chains in Node and
//! classifying every reachable property name. A name absent from a table is
//! `undefined` there, which is [`Resolution::Falsy`].

/// What a property lookup on a prototype-chain value amounts to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Resolution {
    /// The lookup found nothing, or found a falsy value (`undefined`, `0`, `""`,
    /// `null`). The constructor rejects it.
    Falsy,
    /// The lookup found a truthy object or function, whose `[0]` is `undefined`.
    Truthy,
    /// The lookup found a non-empty string; `[0]` is this character, and the
    /// otherwise-dead `Object.create(...)` throws on it.
    FirstChar(char),
    /// Reading `caller` or `arguments` off a built-in function throws.
    Restricted,
}

/// The message the reference engine gives for a restricted function property.
pub const RESTRICTED_MESSAGE: &str = "'caller', 'callee', and 'arguments' properties may not be accessed on strict mode functions or the arguments objects for calls to them";

/// `Object.prototype`'s own property names, in specification order.
pub static OBJECT_PROTOTYPE_NAMES: &[&str] = &[
    "constructor",
    "__defineGetter__",
    "__defineSetter__",
    "hasOwnProperty",
    "__lookupGetter__",
    "__lookupSetter__",
    "isPrototypeOf",
    "propertyIsEnumerable",
    "toString",
    "valueOf",
    "__proto__",
    "toLocaleString",
];

/// Resolution of a property name against a plain object literal — the fallback
/// for `languageFiles[realType][language]` when `language` is not a real one.
pub static LITERAL_FALLBACK: &[(&str, Resolution)] = &[
    ("constructor", Resolution::Truthy),
    ("__defineGetter__", Resolution::Truthy),
    ("__defineSetter__", Resolution::Truthy),
    ("hasOwnProperty", Resolution::Truthy),
    ("__lookupGetter__", Resolution::Truthy),
    ("__lookupSetter__", Resolution::Truthy),
    ("isPrototypeOf", Resolution::Truthy),
    ("propertyIsEnumerable", Resolution::Truthy),
    ("toString", Resolution::Truthy),
    ("valueOf", Resolution::Truthy),
    ("__proto__", Resolution::Truthy),
    ("toLocaleString", Resolution::Truthy),
];

